<?php
require_once __DIR__ . '/includes/bootstrap.php'; adminRequireLogin(); ensureOrderManagementTables(); ensureOrderPaymentsTable();
$conn = adminDb();
function reportRow($sql) { $result = mysqli_query(adminDb(), $sql); return $result ? mysqli_fetch_assoc($result) : array(); }
$summary = reportRow("SELECT COUNT(*) orders_count,COALESCE(SUM(f.total_amount),0) revenue,COALESCE(SUM(f.discount_amount),0) discounts,COALESCE(AVG(f.total_amount),0) average_order FROM orders o LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN order_tracking t ON t.orderid=o.orderid WHERE COALESCE(t.status,'placed') <> 'cancelled'");
$refunds = reportRow("SELECT COALESCE(SUM(amount),0) total,COUNT(*) requests,SUM(status='processed') processed FROM order_refunds");
$statuses = adminRows("SELECT COALESCE(t.status,'placed') status,COUNT(*) total FROM orders o LEFT JOIN order_tracking t ON t.orderid=o.orderid GROUP BY COALESCE(t.status,'placed') ORDER BY total DESC");
$payments = adminRows("SELECT p.payment_method,COUNT(*) total,COALESCE(SUM(f.total_amount),0) revenue FROM order_payments p LEFT JOIN order_financials f ON f.orderid=p.orderid GROUP BY p.payment_method ORDER BY total DESC");
$recent = adminRows("SELECT o.orderid,o.name,f.total_amount,t.status,r.status refund_status FROM orders o LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN order_tracking t ON t.orderid=o.orderid LEFT JOIN order_refunds r ON r.orderid=o.orderid ORDER BY o.orderid DESC LIMIT 10");
$adminTitle='Reports'; $adminPage='reports'; $adminStyles=array('reports.css'); include __DIR__ . '/includes/header.php';
?>
<section class="report-hero"><div><p>Business performance</p><h2>Revenue and order analysis</h2><span>Live figures from active orders, discounts, refunds, and recorded payment methods.</span></div><a class="admin-btn" href="order-details.php"><i class="bi bi-bag" aria-hidden="true"></i> Manage orders</a></section>
<section class="report-kpis"><article><span>Net order revenue</span><strong>Rs <?php echo number_format((float)$summary['revenue']); ?></strong><small>Cancelled orders excluded</small></article><article><span>Orders received</span><strong><?php echo (int)$summary['orders_count']; ?></strong><small>All active order records</small></article><article><span>Discounts given</span><strong>Rs <?php echo number_format((float)$summary['discounts']); ?></strong><small>Offer savings applied</small></article><article><span>Average order</span><strong>Rs <?php echo number_format((float)$summary['average_order']); ?></strong><small>Per non-cancelled order</small></article></section>
<section class="report-grid"><article class="admin-card"><div class="admin-toolbar"><div><h2>Order status</h2><p class="admin-muted">Current operational workload.</p></div></div><div class="report-bars"><?php foreach($statuses as $row){$width=max(8,min(100,(int)$row['total']*18));?><div><span><?php echo adminEscape(ucwords(str_replace('_',' ',$row['status']))); ?></span><b style="width:<?php echo $width;?>%"></b><strong><?php echo (int)$row['total']; ?></strong></div><?php } ?></div></article><article class="admin-card"><div class="admin-toolbar"><div><h2>Refunds</h2><p class="admin-muted">Refund processing overview.</p></div></div><div class="refund-summary"><strong>Rs <?php echo number_format((float)$refunds['total']); ?></strong><span>Refund value recorded</span><div><b><?php echo (int)$refunds['requests']; ?></b> refund records <b><?php echo (int)$refunds['processed']; ?></b> processed</div></div></article></section>
<section class="admin-card"><div class="admin-toolbar"><div><h2>Payment method performance</h2><p class="admin-muted">Orders and recorded value by payment method.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Method</th><th>Orders</th><th>Revenue</th></tr></thead><tbody><?php foreach($payments as $row){?><tr><td><?php echo adminEscape(ucwords($row['payment_method'])); ?></td><td><?php echo (int)$row['total']; ?></td><td><strong>Rs <?php echo number_format((float)$row['revenue']); ?></strong></td></tr><?php } ?></tbody></table></div></section>
<section class="admin-card"><div class="admin-toolbar"><div><h2>Recent financial activity</h2><p class="admin-muted">Use Orders to view items, customer contact details, and delivery changes.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Refund</th><th>Total</th></tr></thead><tbody><?php foreach($recent as $row){?><tr><td>#<?php echo (int)$row['orderid']; ?></td><td><?php echo adminEscape($row['name']); ?></td><td><span class="admin-badge live"><?php echo adminEscape(ucwords(str_replace('_',' ',$row['status']??'placed'))); ?></span></td><td><?php echo adminEscape($row['refund_status'] ? ucwords(str_replace('_',' ',$row['refund_status'])) : 'None'); ?></td><td><strong>Rs <?php echo number_format((float)$row['total_amount']); ?></strong></td></tr><?php } ?></tbody></table></div></section>
